CREATE TABLE IF NOT EXISTS `cms_operation_events` (`id` text PRIMARY KEY NOT NULL, `site_id` text NOT NULL, `category` text NOT NULL, `action` text NOT NULL, `status` text NOT NULL DEFAULT 'success', `severity` text NOT NULL DEFAULT 'info', `entity_type` text, `entity_id` text, `message` text NOT NULL, `metadata` text, `attempts` integer NOT NULL DEFAULT 0, `last_attempt_at` text, `next_retry_at` text, `resolved_at` text, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE INDEX IF NOT EXISTS `cms_operations_site_idx` ON `cms_operation_events` (`site_id`, `created_at`);
CREATE INDEX IF NOT EXISTS `cms_operations_status_idx` ON `cms_operation_events` (`site_id`, `status`, `created_at`);
CREATE TABLE IF NOT EXISTS `cms_delivery_runs` (`site_id` text PRIMARY KEY NOT NULL, `run_id` text NOT NULL, `status` text NOT NULL DEFAULT 'in_progress', `current_step` text NOT NULL DEFAULT 'intake', `package_name` text, `package_summary` text, `import_revision_id` text, `last_error` text, `created_by` text NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE INDEX IF NOT EXISTS `cms_delivery_runs_status_idx` ON `cms_delivery_runs` (`status`, `updated_at`);
